UP="allow update: if isOwner()\n        && request.resource.data.keys().hasOnly(['sid','clientId','status','rev','addedAt','updatedAt','lastAudit'])"
AU="allow create: if isOwner() && aid.matches('^[A-Za-z0-9]{16,40}$')"
PAIR="&& !exists(waAuditRef(request.resource.data.lastAudit)) && existsAfter(waAuditRef(request.resource.data.lastAudit))"
